#include "stdafx.h"#include <rsuFormats.h>#include <math.h>void DblToStr(char* lp,double d, size_t dstSize ){  double ab = fabs(d);  if ( ab < 0.001 || ab > 100000 )  {    if ( d == 0 )      sprintf_s(lp,31,"0");    else      sprintf_s(lp,31,"%.1e",d);  }  else  {    //    char szFrm[8] = "%.3f";    if ( ab > 100 ) szFrm[2] = '0';    else if ( ab >  10 ) szFrm[2] = '1';    else if ( ab >   1 ) szFrm[2] = '2';    //    sprintf_s(lp,dstSize,szFrm,d);    char* pStr = strchr(lp,'.');    if ( pStr == NULL ) //Русифицированный формат      pStr = strchr(lp,',');    if ( pStr )    {      *pStr = '.';//Чтобы избавиться от запятых      char* pTmp = lp + lstrlen(lp)-1;      while (pTmp != pStr && *pTmp == '0' ) *(pTmp--) = '\0';      if ( pTmp == pStr ) *pTmp = '\0';    }  }}